function configure(settings) {
  const { channelId, rowBefore, rowAfter, rowToInsert } = settings;
  if (
    !/^UC[A-Za-z0-9_-]{22}$/.test(channelId) ||
    [rowBefore, rowAfter, rowToInsert].some(
      (line) => typeof line !== "string" || !line.trim() || /[\r\n]/.test(line),
    ) ||
    rowBefore.trim() === rowAfter.trim() ||
    [rowBefore.trim(), rowAfter.trim()].includes(rowToInsert.trim()) ||
    /[<>]/.test(rowToInsert)
  ) {
    throw Error("Enter a YouTube channel ID and three distinct, nonempty single lines.");
  }
  return { channelId, rowBefore: rowBefore.trim(), rowAfter: rowAfter.trim(), rowToInsert };
}
const settings = {
  channelId: "YOUR_YOUTUBE_CHANNEL_ID",
  rowBefore: "Resources",
  rowAfter: "Credits",
  rowToInsert: "https://example.com/resources",
};
return [{ json: configure(settings) }];

function ownedUploads(channels, channelId) {
  const matches = Array.isArray(channels) ? channels.filter((ch) => ch.id === channelId) : [];
  const playlist = matches[0]?.contentDetails?.relatedPlaylists?.uploads;
  if (
    matches.length !== 1 ||
    typeof playlist !== "string" ||
    !/^UU[A-Za-z0-9_-]{22}$/.test(playlist)
  ) {
    throw Error(
      "The connected YouTube account did not confirm the configured channel and uploads playlist.",
    );
  }
  return playlist;
}
const packet = $input.first().json;
if (packet.statusCode !== 200) throw Error("YouTube did not confirm the channel.");
const settings = $("Set the channel and description lines").first().json;
const playlistId = ownedUploads(packet.body?.items, settings.channelId);
return [{ json: { playlistId } }];

function selectedVideos(items, playlist) {
  if (!Array.isArray(items) || items.length > 3)
    throw Error("YouTube returned an unexpected uploads list.");
  const ids = items.map((row) => {
    const id = row.contentDetails?.videoId;
    if (
      !/^[A-Za-z0-9_-]{11}$/.test(id ?? "") ||
      (row.snippet?.playlistId && row.snippet.playlistId !== playlist)
    ) {
      throw Error("The uploads list contains an invalid video.");
    }
    return id;
  });
  if (new Set(ids).size !== ids.length) throw Error("The uploads list contains a repeated video.");
  return ids;
}
const packet = $input.first().json,
  playlist = $("Select the verified uploads playlist").first().json.playlistId;
if (packet.statusCode !== 200) throw Error("YouTube did not return the uploads playlist.");
const ids = selectedVideos(packet.body?.items, playlist);
return ids.length ? [{ json: { ids, joined: ids.join(",") } }] : [];

function planUpdates(videos, ids, settings) {
  if (
    !Array.isArray(videos) ||
    videos.some((video) => !ids.includes(video.id)) ||
    new Set(videos.map((video) => video.id)).size !== videos.length
  ) {
    throw Error("YouTube returned unexpected video IDs.");
  }
  const jobs = [],
    results = [];
  for (const id of ids) {
    const video = videos.find((item) => item.id === id);
    const snippet = video?.snippet;
    const result = (status) => results.push({ videoId: id, status });
    if (!snippet || snippet.channelId !== settings.channelId) {
      result("ownership_unconfirmed");
      continue;
    }
    if (
      typeof snippet.description !== "string" ||
      typeof snippet.title !== "string" ||
      !snippet.title ||
      !/^\d+$/.test(snippet.categoryId ?? "") ||
      (Object.hasOwn(snippet, "tags") &&
        (!Array.isArray(snippet.tags) || snippet.tags.some((tag) => typeof tag !== "string"))) ||
      (Object.hasOwn(snippet, "defaultLanguage") && typeof snippet.defaultLanguage !== "string")
    ) {
      result("snippet_unconfirmed");
      continue;
    }
    const pieces = snippet.description.split(/(\r\n|\r|\n)/);
    const rows = pieces.filter((_, index) => index % 2 === 0);
    const before = rows.findIndex((line) => line.trim() === settings.rowBefore);
    const after = rows.findIndex((line) => line.trim() === settings.rowAfter);
    if (before < 0 || after <= before) {
      result("markers_not_ordered");
      continue;
    }
    if (rows.includes(settings.rowToInsert)) {
      result("already_present");
      continue;
    }
    const raw = video.etag;
    if (typeof raw !== "string" || !/^"?[A-Za-z0-9_+/=-]+"?$/.test(raw)) {
      result("etag_unconfirmed");
      continue;
    }
    const etag = '"' + raw.replaceAll('"', "") + '"';
    const separator = pieces[2 * before + 1];
    pieces.splice(2 * before + 2, 0, settings.rowToInsert, separator);
    const description = pieces.join("");
    const body = {
      id,
      snippet: { title: snippet.title, categoryId: snippet.categoryId, description },
    };
    for (const field of ["tags", "defaultLanguage"])
      if (Object.hasOwn(snippet, field)) body.snippet[field] = snippet[field];
    jobs.push({ videoId: id, channelId: settings.channelId, etag, body });
  }
  return { jobs, results };
}
const packet = $input.first().json;
if (packet.statusCode !== 200) throw Error("YouTube did not return the selected videos.");
const settings = $("Set the channel and description lines").first().json;
const ids = $("Select those video IDs").first().json.ids;
return planUpdates(packet.body?.items, ids, settings).jobs.map((job) => ({
  json: job,
  pairedItem: { item: 0 },
}));

function checkedReceipt(job, status, body) {
  if (status === 412) return { videoId: job.videoId, status: "changed_since_read" };
  const same =
    body?.id === job.videoId &&
    body.snippet?.channelId === job.channelId &&
    Object.entries(job.body.snippet).every(
      ([key, val]) => JSON.stringify(val) === JSON.stringify(body.snippet[key]),
    );
  return {
    videoId: job.videoId,
    status: status === 200 && same ? "updated" : "update_unconfirmed",
  };
}
const job = $("Plan exact description updates").item.json;
return {
  json: checkedReceipt(job, $json.statusCode, $json.body),
  pairedItem: { item: $itemIndex },
};
